body {
  font-family: 'Roboto', Arial, sans-serif;
  color: #222222;
  background-color: #FFFFFF;
}
.main-nav {
  background-color: #FFFFFF;
  border-bottom: 2px solid #0D3B66;
}
.main-nav a {
  color: #0D3B66;
  font-weight: 700;
  letter-spacing: 0.5px;
  padding: 12px 16px;
}
.news-post {
  border-bottom: 1px solid #F4F4F4;
  padding: 16px 0;
}
.news-post .date {
  color: #1E88C7;
  font-size: 12px;
  font-weight: 700;
}
.spokesperson-widget {
  background-color: #F4F4F4;
  padding: 20px;
  border-left: 3px solid #0D3B66;
}
.load-more-btn {
  background-color: #0D3B66;
  color: #FFFFFF;
  padding: 10px 24px;
  border: none;
}

